mapper.select:
SELECT p.id AS id, p.subject AS subject, p.category_id AS categoryId, cat.name AS categoryName, p.status AS status, p.public_access AS publicAccess, p.main_page AS mainPage, (d.post_id IS NOT NULL) AS hasDraft, p.view_count AS viewCount, (SELECT COUNT(*) FROM tb_post_tag_map m WHERE m.post_id = p.id) AS tagCount, p.created_at AS createdAt, p.updated_at AS updatedAt FROM tb_post AS p LEFT JOIN tb_category cat ON p.category_id = cat.id LEFT JOIN tb_post_draft d ON d.post_id = p.id
AND LOWER(p.subject) LIKE CONCAT('%', LOWER(#{subject}), '%')
AND cat.full_path LIKE CONCAT('%/', #{categoryId}, '/%')
AND p.status = #{status}
AND p.public_access = #{publicAccess}
AND d.post_id IS NOT NULL
AND d.post_id IS NULL
AND p.view_count >= #{minViewCount}
AND p.view_count <= #{maxViewCount}
AND >= #{dateFrom}
AND < #{dateToExclusive}
AND EXISTS ( SELECT 1 FROM tb_post_tag_map m JOIN tb_tag t ON t.id = m.tag_id WHERE m.post_id = p.id AND LOWER(t.name) LIKE CONCAT('%', LOWER(#{tagName}), '%') )

SELECT COALESCE(prev_post.id, 0) AS PREV , COALESCE(next_post.id, 0) AS NEXT , prev_post.subject AS PREV_SUBJECT , next_post.subject AS NEXT_SUBJECT FROM (SELECT 1) AS dummy LEFT JOIN (
SELECT id, subject FROM tb_post WHERE id < #{id}
AND public_access = true AND status = 'PUB'
ORDER BY id DESC LIMIT 1 ) prev_post ON true LEFT JOIN ( SELECT id, subject FROM tb_post WHERE id > #{id}
AND public_access = true AND status = 'PUB'
ORDER BY id ASC LIMIT 1 ) next_post ON true
